import { useThrottleEffect } from 'ahooks'
import { useEffect, useMemo, useRef, useState } from 'react'

export default function useDlmmGroupListInteraction<T>(allData: T[], pageSize = 10, isOpen: boolean) {
  const [isLoadMoreLoading, setIsLoadMoreLoading] = useState(false)
  const loadMoreRef = useRef<HTMLDivElement>(null)
  const [list, setList] = useState<T[]>([])
  const [currentPage, setCurrentPage] = useState<number>(1)
  const [hasLoadMore, setHasLoadMore] = useState<boolean>(true)
  const containerRef = useRef<HTMLDivElement>(null)

  // 监听展开状态变化，重置滚动位置
  useEffect(() => {
    if (isOpen && containerRef.current) {
      containerRef.current?.scrollTo({ top: 0 })
    }
  }, [isOpen]) // 依赖 isOpen 状态

  const totalPage = useMemo(() => {
    return allData?.length <= pageSize ? 1 : Math.ceil((allData.length - pageSize) / pageSize) + 1
  }, [allData?.length, pageSize])

  useEffect(() => {
    if (isOpen) {
      setList(allData?.slice(0, pageSize))
    }
  }, [isOpen, pageSize])

  useEffect(() => {
    if (!isOpen) {
      setList([])
      setCurrentPage(1)
      setHasLoadMore(true)
      setIsLoadMoreLoading(false)
    }
  }, [isOpen])

  useEffect(() => {
    let observer: IntersectionObserver | null = null
    if (loadMoreRef.current) {
      observer = new IntersectionObserver(
        entries => {
          // 使用防抖处理，避免多次触发
          const entry = entries[0]
          if (entry && entry.isIntersecting && hasLoadMore && !isLoadMoreLoading) {
            if (currentPage < totalPage) {
              setIsLoadMoreLoading(true)
              // console.log('🚀 ~ useEffect ~ entry:', entry)
              setCurrentPage(pre => pre + 1)
            }
          }
        },
        { threshold: 1 }
      )
      observer.observe(loadMoreRef.current!)
    }

    // 清理函数
    return () => {
      if (observer) {
        observer.disconnect()
      }
    }
  }, [hasLoadMore, isLoadMoreLoading, totalPage, currentPage])

  useEffect(() => {
    if (currentPage >= totalPage) {
      setHasLoadMore(false)
      setIsLoadMoreLoading(false)
    }
  }, [currentPage, totalPage])

  useThrottleEffect(
    () => {
      setTimeout(() => {
        if (currentPage > 1) {
          const oldList = [...list]
          const newList = allData.slice(0, oldList?.length + pageSize)

          setList(newList)
          setIsLoadMoreLoading(false)
        }
      }, 300)
    },
    [currentPage, pageSize],
    {
      wait: 300
    }
  )

  return {
    hasLoadMore,
    loadMoreRef,
    isLoadMoreLoading,
    list,
    containerRef
  }
}
